const b = $input.first().json.body || $input.first().json;
const uuid = (b.uuid || '').toString();
const typePost = (b.type_post || '').toString();
const message = (b.message || '').toString();
const signerEmail = (b.email || '').toString().toLowerCase().trim();

// Evento de assinatura individual ("Signed" / type_post 4) — traz o e-mail de quem assinou
const ehAssinatura = typePost === '4' || /signed|assinad/i.test(message);

// Cliente = e-mail que NÃO é @example.com (internos: financeiro, pos-venda, etc.)
const ehCliente = !!signerEmail && !/@example\.com$/i.test(signerEmail);

// Dedupe: 1 e-mail por documento (se o contrato tiver mais de 1 assinante do cliente)
const staticData = $getWorkflowStaticData('global');
const processados = staticData.processados || {};
const jaProcessado = !!(uuid && processados[uuid]);

const processar = ehAssinatura && ehCliente && !jaProcessado;
if (processar) { processados[uuid] = true; staticData.processados = processados; }

return [{ json: { uuid, typePost, message, signerEmail, ehAssinatura, ehCliente, jaProcessado, processar } }];

const texto = ($input.first().json.text || "").toUpperCase();
const textoOrig = $input.first().json.text || "";
const PALAVRAS = [
  "PROPOSTA COMERCIAL",
  "ACEITE DA PROPOSTA",
  "DO FORO",
  "DO PRAZO E RESCIS",
  "TAXA DE ADES",
  "TREINAMENTO E SUPORTE",
  "DETALHES DA CONTRATA",
  "VALIDADE DA PROPOSTA",
  "OBSERVA",
  "DADOS DA CONTRATA",
  "VALORES DE CONTRATA",
  "ADES",
  "FUNCIONALIDADES DO SISTEMA",
  "FUNCIONALIDADES DO PLANO",
];
const faltando = PALAVRAS.filter((p) => !texto.includes(p));
const propostaOk = faltando.length === 0;
const m = texto.replace(/[^0-9]/g, " ").match(/\b(\d{14})\b/);
const cnpj = m ? m[1] : "";
let enderecoPdf = "";
const emd = texto.match(/ENDERE[CÇ]O:?(.*?)(CIDADE:|UF:|CEP:|$)/s);
if (emd) enderecoPdf = emd[1].replace(/\s+/g, " ").trim();
const mr = texto.match(/RAZ[ÃA]O SOCIAL\s*:?\s*([^\n]+)/);
const razaoPdf = mr ? mr[1].trim() : "";
function normTel(s) {
  let d = String(s || "").replace(/\D/g, "");
  if (d.length > 11 && d.startsWith("55")) d = d.slice(2);
  d = d.replace(/^0+/, "");
  return d;
}
let emailBoleto = "";
const mb = textoOrig.match(
  /RECEBER OS BOLETOS[\s\S]{0,250}?e-?mail\s*:?\s*([^\s]+@[^\s]+)/i,
);
if (mb)
  emailBoleto = mb[1]
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9@._+-]/g, "");
let telBoleto = "";
const mtb = textoOrig.match(
  /RECEBER OS BOLETOS[\s\S]{0,300}?(?:celular|telefone|cel|fone)\s*:?\s*\+?([\d().\s-]{8,})/i,
);
if (mtb) telBoleto = normTel(mtb[1]);
const blocosEmail = [
  /RESPONS[ÁA]VEL PELO CONTRATO[\s\S]{0,300}?e-?mail\s*:?\s*([^\s]+@[^\s]+)/i,
  /RECEBER OS BOLETOS[\s\S]{0,300}?e-?mail\s*:?\s*([^\s]+@[^\s]+)/i,
  /IMPLANTA[ÇC][ÃA]O DO SISTEMA[\s\S]{0,300}?e-?mail\s*:?\s*([^\s]+@[^\s]+)/i,
];
let emailsPdf = [];
for (const rx of blocosEmail) {
  const mm = textoOrig.match(rx);
  if (mm) emailsPdf.push(mm[1].toLowerCase().replace(/[^a-z0-9@._+-]/g, ""));
}
emailsPdf = Array.from(new Set(emailsPdf)).filter(
  (e) => e && !/@example\.com$/i.test(e),
);
let telefonesPdf = [];
const labelsTel = [
  /RESPONS[ÁA]VEL PELO CONTRATO/i,
  /RECEBER OS BOLETOS/i,
  /IMPLANTA[ÇC][ÃA]O DO SISTEMA/i,
];
for (const lab of labelsTel) {
  const idx = textoOrig.search(lab);
  if (idx < 0) continue;
  const bloco = textoOrig.slice(idx, idx + 350);
  const fones =
    bloco.match(/(?:telefone|celular|cel|fone)\s*:?\s*\+?[\d()\s.-]{8,}/gi) ||
    [];
  for (const f of fones) {
    const d = normTel(f);
    if (d.length >= 10) telefonesPdf.push(d);
  }
}
telefonesPdf = Array.from(new Set(telefonesPdf));
const freeMail = [
  "gmail.com",
  "hotmail.com",
  "outlook.com",
  "outlook.com.br",
  "hotmail.com.br",
  "yahoo.com",
  "yahoo.com.br",
  "icloud.com",
  "bol.com.br",
  "uol.com.br",
  "terra.com.br",
  "live.com",
  "msn.com",
  "ig.com.br",
  "globo.com",
  "r7.com",
  "me.com",
  "protonmail.com",
];
const dominiosPdf = Array.from(
  new Set(
    emailsPdf
      .map((e) => (e.split("@")[1] || "").toLowerCase())
      .filter((d) => d && !freeMail.includes(d) && !/example\.com/i.test(d)),
  ),
);
// Vendedor (Representante comercial no contrato)
let vendedor = "";
const mv = textoOrig.match(/([^\n]{2,60}?)\s*\r?\n\s*Representante comercial/i);
if (mv) vendedor = mv[1].replace(/^[\s•*\-]+/, "").trim();
return [
  {
    json: {
      propostaOk,
      palavrasFaltando: faltando,
      cnpj,
      enderecoPdf,
      razaoPdf,
      emailBoleto,
      telBoleto,
      emailsPdf,
      telefonesPdf,
      dominiosPdf,
      vendedor,
    },
  },
];

const raw = $('D4Sign: lista signatarios').all().map(i=>i.json);
let signers=[]; for(const r of raw){ if(!r) continue; if(Array.isArray(r.list)) signers.push(...r.list); else if(r.user_name) signers.push(r); else if(Array.isArray(r)) signers.push(...r); }
const cliente = signers.find(s => s && s.email && !/@example\.com$/i.test((s.email||'').trim()));
let razao=''; try{ razao=$('Valida proposta + extrai CNPJ').first().json.razaoPdf||''; }catch(e){}
if(!razao){ try{ razao=((($('Consulta cnpja').first().json)||{}).company||{}).name||''; }catch(e){} }
razao=String(razao).replace(/'/g,'').trim();
const stop=['LTDA','ME','EPP','SA','EIRELI','EIRELLI','DE','DA','DO','DOS','DAS','E','&','-'];
const limpa=razao.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ');
const palavras=limpa.split(/\s+/).filter(w=>w.length>=3 && !stop.includes(w));
const razao_busca=(palavras[0]||'').replace(/'/g,'');
let emailsPdf=[], telefonesPdf=[], dominiosPdf=[];
try{ const v=$('Valida proposta + extrai CNPJ').first().json; emailsPdf=v.emailsPdf||[]; telefonesPdf=v.telefonesPdf||[]; dominiosPdf=v.dominiosPdf||[]; }catch(e){}
if(cliente && cliente.email) emailsPdf.push(cliente.email.toLowerCase().trim());
emailsPdf=Array.from(new Set(emailsPdf.map(e=>String(e||'').toLowerCase().trim()))).filter(Boolean);
const emailsIn=emailsPdf.map(e=>"'"+e.replace(/'/g,'')+"'").join(',')||"''";
const telClean="p.cliente_pipedrive_pessoa_telefone";
const telefonesLike=telefonesPdf.length ? telefonesPdf.map(t=>telClean+" LIKE '%"+String(t).replace(/\D/g,'').slice(-8)+"%'").join(' OR ') : "1=0";
const dominiosLike=dominiosPdf.length ? dominiosPdf.map(d=>"p.cliente_pipedrive_pessoa_email LIKE '%@"+String(d).replace(/'/g,'')+"'").join(' OR ') : "1=0";
return [{ json: { email_cliente: cliente?cliente.email.toLowerCase().trim():'', razao, razao_busca, emailsPdf, emailsIn, telefonesPdf, telefonesLike, dominiosPdf, dominiosLike } }];

const r = $input.first().json || {};
let t = '';
if (r.data && typeof r.data.text === 'string') t = r.data.text;
else if (typeof r.text === 'string') t = r.text;
else if (typeof r.data === 'string') t = r.data;
const m = String(t).match(/\d{1,7}/);
const proposta_id = m ? m[0] : '';
let cnpj = '';
try { cnpj = String($('Valida proposta + extrai CNPJ').first().json.cnpj || '').replace(/\D/g,''); } catch(e) {}
return [{ json: { proposta_id, cnpj } }];

const prop = $('Busca proposta cadastro').first().json;
const extras = $('Busca extras cadastro').all().map(i => i.json).filter(e => e && e.plano_id);
let cnpja = {}; try { cnpja = $('Consulta cnpja').first().json || {}; } catch(e) {}
const cnpj = $('Lê resposta (ID proposta)').first().json.cnpj;

// e-mail + celular de quem recebe os boletos (do contrato)
let emailBoleto = '', telBoleto = '';
try { const v = $('Valida proposta + extrai CNPJ').first().json; emailBoleto = v.emailBoleto || ''; telBoleto = v.telBoleto || ''; } catch(e) {}

// Telefone (de cima): da proposta, separado em DDD + numero
let telDig = String(prop.contato_telefone || '').replace(/\D/g,'');
if (telDig.length > 11 && telDig.startsWith('55')) telDig = telDig.slice(2);
const ddd = telDig.length >= 10 ? telDig.slice(0,2) : '';
const telefone = telDig.length >= 10 ? telDig.slice(2) : telDig;
// Celular (de baixo): de quem recebe o boleto (DDD + numero juntos)
const celular = String(telBoleto || '').replace(/\D/g,'');

const MODO_TESTE = false;
const achou = !MODO_TESTE && !!(cnpja && cnpja.company && cnpja.company.name);
const end = (achou && cnpja.address) ? cnpja.address : {};
const simples = achou ? !!(cnpja.company.simples && cnpja.company.simples.optant) : false;
const razao = achou ? cnpja.company.name : 'TESTE AUTOMACAO LTDA';
const fantasia = achou ? (cnpja.alias || razao) : 'TESTE AUTOMACAO';
const email = MODO_TESTE ? 'teste@example.com' : (emailBoleto || prop.contato_email || '');

const nome = (prop.plano_nome || '').toLowerCase();
const parcelas = Number(prop.plano_quantidade_parcela) || 0;
const periodicidade = Number(prop.plano_periodicidade) || 0;
const recorrente = parcelas === periodicidade || parcelas === 0 || periodicidade === 0;
const mapMensal = { 'da vinci':12, 'monet':10, 'munch':20, 'van gogh':11, 'michelangelo':15 };
const mapAvista = { 'da vinci':23, 'monet':33, 'munch':24 };
function acha(map){ for (const k of Object.keys(map)) if (nome.includes(k)) return map[k]; return null; }
let idPlano = recorrente ? acha(mapMensal) : (acha(mapAvista) || acha(mapMensal));
const tipoPlano = recorrente ? 'recorrente (mensal)' : 'a vista';
const reterImpostos = simples ? 0 : 1;

const out = {
  cnpj, cnpja_encontrou: achou,
  cliente: { razao_social: razao, nome_fantasia: fantasia, cnpj, email,
    ddd, telefone, celular,
    dia_vencimento: prop.plano_dia_vencimento || 10,
    logradouro: end.street || '', numero: String(end.number || ''), bairro: end.district || '',
    cidade: end.city || '', uf: end.state || '', cep: String(end.zip || ''),
    simples, fl_optante_simples: simples ? 1 : 0, reter_impostos: reterImpostos },
  assinatura: { id_plano: idPlano, plano_nome_gpc: prop.plano_nome, tipo_plano: tipoPlano,
    valor_negociado: prop.plano_valor_final, parcelas, periodicidade,
    dia_vencimento: prop.plano_dia_vencimento || 10, notificar_cliente: 1 },
  extras: extras.map(e => ({ plano_id: e.plano_id, nome: e.plano_nome, valor: e.valor })),
  adesao: { valor: prop.adesao_valor_final, parcelas: prop.adesao_quantidade_parcela || 1 },
  proposta_id: prop.proposta_id
};
return [{ json: out }];

// Monta o corpo da assinatura: base + extras + adesão como ITENS (OPCIONAIS)
const dados = $('Monta dados + de-para').first().json;
const cli = $('Cadastra cliente').first().json;
const idSacado = (cli.data && cli.data.id_sacado_sac) || cli.id_sacado_sac || (cli.data && cli.data[0] && cli.data[0].id_sacado_sac) || '';

const mapProd = {
  'controle de estoque':14, 'nf-e':16, 'nfe':16, 'alçada':15, 'alcada':15,
  'mão de obra':32, 'mao de obra':32, 'asaas':44, 'aplicativo':18, 'portal do cliente':17,
  'bi personalizado':37, 'bancária':38, 'bancaria':38, 'gestão de tarefas':43, 'gestao de tarefas':43,
  'contratos':42, 'orçafascio':40, 'orcafascio':40, 'pagamentos':41, 'cobrança':35, 'cobranca':35
};
function achaProd(n){ const s=(n||'').toLowerCase(); for(const k of Object.keys(mapProd)) if(s.includes(k)) return mapProd[k]; return null; }

const d = new Date();
const dt = String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+'/'+d.getFullYear();

const body = {};
body['PLANOS[0][ID_SACADO_SAC]'] = idSacado;
body['PLANOS[0][ID_PLANO_PLA]'] = dados.assinatura.id_plano;
body['PLANOS[0][DT_CONTRATO_PLC]'] = dt;
body['PLANOS[0][FL_NOTIFICARCLIENTE]'] = 1;
body['PLANOS[0][FL_MULTIPLO_COMPO]'] = 1;
body['PLANOS[0][QUANT_PARCELAS_ADESAO]'] = dados.adesao.parcelas || 1;

let i = 0;
function add(prd, val, rec){
  body['OPCIONAIS['+i+'][ID_PRODUTO_PRD]'] = prd;
  body['OPCIONAIS['+i+'][SELECIONAR_PRODUTO]'] = 1;
  body['OPCIONAIS['+i+'][NM_QNTD_PLP]'] = 1;
  body['OPCIONAIS['+i+'][valor_unitario]'] = val;
  body['OPCIONAIS['+i+'][FL_RECORRENTE_PLP]'] = rec;
  i++;
}

add(11, dados.assinatura.valor_negociado, 1);
const naoMapeados = [];
for (const ex of (dados.extras || [])) {
  const p = achaProd(ex.nome);
  if (p) add(p, ex.valor, 1); else naoMapeados.push(ex.nome);
}
if (Number(dados.adesao.valor) > 0) add(12, dados.adesao.valor, 0);

const parts = [];
for (const k in body) parts.push(encodeURIComponent(k)+'='+encodeURIComponent(body[k]));

return [{ json: { raw: parts.join('&'), body, naoMapeados, id_sacado: idSacado } }];

const dados = $('Monta dados + de-para').first().json;
const corpo = $('Monta body assinatura').first().json;
const resp = $('Cadastra assinatura (base+extras+adesao)').first().json;
const d = (resp && resp.data) ? resp.data : (Array.isArray(resp) && resp[0] && resp[0].data) ? resp[0].data : {};
const idCli = d.id_sacado_sac || corpo.id_sacado || '';
const urlCliente = idCli ? 'https://suaempresa.superlogica.net/clients/financeiro/sacados/id/' + idCli : '';

function fmt(v){ const n = Number(v||0); return 'R$ ' + n.toLocaleString('pt-BR',{minimumFractionDigits:2, maximumFractionDigits:2}); }

const extrasLinhas = (dados.extras||[]).map(e => `<p style="margin:2px 0;font-size:13px;">• ${e.nome}: <strong>${fmt(e.valor)}</strong></p>`).join('');
const aviso = (corpo.naoMapeados && corpo.naoMapeados.length)
  ? `<p style="color:#b00;margin:10px 0;font-size:13px;">⚠️ Extras SEM de-para (não cadastrados): ${corpo.naoMapeados.join(', ')}</p>` : '';

const html = `
<div style="max-width:560px;margin:0 auto;font-family:Arial,Helvetica,sans-serif;color:#2b2b2b;text-align:left;border:1px solid #e6e6e6;border-radius:8px;overflow:hidden;">
  <div style="background:#E8A317;padding:16px 20px;">
    <span style="color:#fff;font-size:18px;font-weight:bold;">✅ Cliente cadastrado no Superlógica</span>
  </div>
  <div style="padding:20px;">
    <p style="margin:0 0 4px;font-size:15px;"><strong>${dados.cliente.razao_social}</strong></p>
    <p style="margin:0 0 2px;font-size:13px;color:#555;">CNPJ: ${dados.cliente.cnpj}</p>
    <p style="margin:0 0 2px;font-size:13px;color:#555;">Plano: ${dados.assinatura.plano_nome_gpc} — ${dados.assinatura.tipo_plano}</p>
    <p style="margin:0 0 2px;font-size:13px;color:#555;">Superlógica ${d.id_sacado_sac || ''}</p> 
    <p style="margin:0 0 16px;font-size:13px;color:#555;">Pipedrive ${$('Busca proposta cadastro').first().json.deal_id || ''}</p>
    <table style="width:100%;border-collapse:collapse;background:#FCF6E8;border-radius:6px;margin-bottom:18px;">
      <tr><td style="padding:12px 14px;font-size:13px;color:#555;border-bottom:1px solid #e6e6e6;">Mensalidade (recorrente)</td><td style="padding:12px 14px;font-size:15px;font-weight:bold;text-align:right;border-bottom:1px solid #e6e6e6;">${fmt(d.vl_aproxrenovacao_plc)}</td></tr>
      <tr><td style="padding:12px 14px;font-size:13px;color:#555;border-bottom:1px solid #e6e6e6;">Taxa de adesão (uma vez)</td><td style="padding:12px 14px;font-size:14px;text-align:right;border-bottom:1px solid #e6e6e6;">${fmt(dados.adesao.valor)}</td></tr>
      <tr><td style="padding:12px 14px;font-size:13px;color:#555;">1º boleto</td><td style="padding:12px 14px;font-size:14px;font-weight:bold;text-align:right;color:#E8A317;">${fmt(d.valor_boleto)}</td></tr>
    </table>
    <p style="margin:0 0 6px;font-size:13px;font-weight:bold;color:#333;">Itens recorrentes</p>
    <p style="margin:2px 0;font-size:13px;">• Mensalidade do plano: <strong>${fmt(dados.assinatura.valor_negociado)}</strong></p>
    ${extrasLinhas}
    ${aviso}
    <p style="margin:20px 0 6px;"><a href="${d.link_boleto || '#'}" style="display:inline-block;background:#E8A317;color:#fff;padding:11px 22px;text-decoration:none;border-radius:5px;font-size:14px;font-weight:bold;margin:0 8px 8px 0;">Ver 1º boleto</a>${urlCliente ? '<a href="'+urlCliente+'" style="display:inline-block;background:#fff;color:#C8860B;border:1px solid #E8A317;padding:10px 22px;text-decoration:none;border-radius:5px;font-size:14px;font-weight:bold;">Ver cliente no Superlógica</a>' : ''}</p>
    <p style="margin:18px 0 0;font-size:11px;color:#999;">Proposta ${dados.proposta_id} • cadastro automático</p>
  </div>
</div>`;

const assunto = `Cadastro Superlógica: ${dados.cliente.razao_social}`;
return [{ json: { html, assunto } }];

const cnpja = (() => { try { return $('Consulta cnpja').first().json || {}; } catch(e){ return {}; } })();
const company = cnpja.company || {};
const razao = company.name || 'Empresa';
let cnpjDig = '';
try { cnpjDig = String($('Valida proposta + extrai CNPJ').first().json.cnpj || '').replace(/\D/g,''); } catch(e){}
if (!cnpjDig) cnpjDig = String(cnpja.taxId || cnpja.tax_id || '').replace(/\D/g,'');
const fmtCnpj = d => d.length===14 ? d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,'$1.$2.$3/$4-$5') : (d||'-');
const capital = (company.equity!=null) ? ('R$ ' + Number(company.equity).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})) : '-';
const membros = (company.members||[]).map(m => ({ nome:(m.person&&m.person.name)||'', papel:(m.role&&m.role.text)||'', cod:(m.role&&m.role.id)||'' }));

const SMAP = { '—':'\x97','–':'\x96','’':'\x92','‘':'\x91','“':'\x93','”':'\x94','•':'\x95','…':'\x85' };
const sanitize = s => { let o=''; for (const ch of String(s)){ if(SMAP[ch]) o+=SMAP[ch]; else if(ch.charCodeAt(0)<=255) o+=ch; else o+='?'; } return o; };
const escPdf = s => sanitize(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
const HW = {32:278,33:278,34:355,35:556,36:556,37:889,38:667,39:191,40:333,41:333,42:389,43:584,44:278,45:333,46:278,47:278,48:556,49:556,50:556,51:556,52:556,53:556,54:556,55:556,56:556,57:556,58:278,59:278,60:584,61:584,62:584,63:556,64:1015,65:667,66:667,67:722,68:722,69:667,70:611,71:778,72:722,73:278,74:500,75:667,76:556,77:833,78:722,79:778,80:667,81:778,82:722,83:667,84:611,85:722,86:667,87:944,88:667,89:667,90:611,91:278,92:278,93:278,94:469,95:556,96:333,97:556,98:556,99:500,100:556,101:556,102:278,103:556,104:556,105:222,106:222,107:500,108:222,109:833,110:556,111:556,112:556,113:556,114:333,115:500,116:278,117:556,118:500,119:722,120:500,121:500,122:500,123:334,124:260,125:334,126:584};
const charW = c => (HW[c]!==undefined?HW[c]:556);
const textW = (t,size,bold) => { let w=0; for(let i=0;i<t.length;i++) w+=charW(t.charCodeAt(i)); return w/1000*size*(bold?1.06:1); };
const wrap = (text,maxW,size,bold) => { const out=[]; for(const word of String(text).split(/\s+/)){ if(!out.length){out.push(word);continue;} const t=out[out.length-1]+' '+word; if(textW(t,size,bold)<=maxW) out[out.length-1]=t; else out.push(word);} return out.length?out:['']; };

const PAGE_W=595.28, PAGE_H=841.89, MARGIN=48;
const pages=[]; let ops=[]; let y;
const newPage=()=>{ if(ops.length) pages.push(ops); ops=[]; y=PAGE_H-MARGIN; };
newPage();
