// ---------- utilitários ----------
const norm = s => (s||'').toString()
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toUpperCase().replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim();

function normTel(s){
  let d = String(s||'').replace(/\D/g,'');
  if(d.length>11 && d.startsWith('55')) d = d.slice(2);
  return d.replace(/^0+/,'');
}

// achata as várias formas que o node do D4Sign pode retornar
function flattenSigners(nodes){
  const out = [];
  for (const r of (nodes||[])){
    if(!r) continue;
    if(Array.isArray(r.list))    out.push(...r.list);
    else if(r.user_name)         out.push(r);
    else if(Array.isArray(r))    out.push(...r);
  }
  return out;
}

// procura o 1o assinante que também esteja no quadro societário
function matchSocio(clienteSigners, membros){
  for (const cs of clienteSigners){
    const csn = norm(cs.user_name);
    const hit = membros.find(m => {
      const mn = norm(m.nome);
      return csn && mn && (mn.includes(csn) || csn.includes(mn));
    });
    if(hit) return hit;
  }
  return null;
}

// escolhe as propostas do cliente por prioridade: e-mail > telefone > domínio > razão > todas
function selectPropostas(cand, clientInfo){
  cand = cand || [];
  const emailsPdf    = (clientInfo.emailsPdf||[]).map(e=>(e||'').toLowerCase());
  const telefonesPdf = (clientInfo.telefonesPdf||[]);
  const dominiosPdf  = (clientInfo.dominiosPdf||[]).map(d=>(d||'').toLowerCase());
  const razaoCli     = norm(clientInfo.razao);

  const stopw  = ['LTDA','ME','EPP','SA','EIRELI','EIRELLI','DE','DA','DO','DOS','DAS','E'];
  const tokens = razaoCli.split(' ').filter(w=>w.length>=3 && !stopw.includes(w)).slice(0,2);

  const telMatch = p => {
    const g = normTel(p.telefone);
    if(!g) return false;
    return telefonesPdf.some(t0 => {
      const t = normTel(t0);
      if(!t) return false;
      if(g===t) return true;
      if(g.slice(-8)===t.slice(-8) && g.slice(0,2)===t.slice(0,2)) return true;
      if(g.endsWith(t) || t.endsWith(g)) return true;
      return false;
    });
  };
  const domMatch = p => {
    const d = ((p.email||'').toLowerCase().split('@')[1]) || '';
    return d && dominiosPdf.includes(d);
  };

  const porEmail    = cand.filter(p => emailsPdf.includes((p.email||'').toLowerCase()));
  const porTelefone = cand.filter(telMatch);
  const porDominio  = cand.filter(domMatch);
  const porRazao    = cand.filter(p => tokens.length && tokens.every(t => norm(p.organizacao).includes(t)));

  return porEmail.length ? porEmail
       : porTelefone.length ? porTelefone
       : porDominio.length ? porDominio
       : porRazao.length ? porRazao
       : cand;
}

